    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "Muchoftheevidenceremainsverylowcertainty,andweanticipate that future studies evaluating drugs for prophylaxis may substantially change the results, particularly for outcomes of laboratory confirmed SARS-CoV-2 infection and mortality.",
      "reason": "The manuscript explicitly states the current state of the evidence (much remains very low certainty) and notes important uncertainty that future studies may substantially change results."
