{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Weincluded randomised trials of people at risk of covid-19 that compared drugs, therapeutic doses of vitamins, or antibodies for prophylaxis against one another or against no prophylaxis (placebo or standard care, as defined by the researchers), with no restriction onlanguageofpublication. We included studies addressing people pre- or post-exposure to covid-19 and at low risk (e.g. unexposed community member) or high risk (e.g. member of the same household with one or more positive cases, contact of index case, healthcare worker or long term care resident) for covid-19.",
      "reason": "The methods explicitly list eligible study design (randomised trials), eligible interventions (drugs, vitamins, antibodies), comparator (no prophylaxis/placebo/standard care), participant exposure status (pre- or post-exposure), and risk groups (low/high), satisfying specification of study characteristics used for eligibility."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "Weexcluded randomised trials published only as press releases and trials that evaluated vaccination, nutrition, and non-drug supportive care interventions.",
      "reason": "The review specifies some report/publication-status criteria (excluded press-release-only trials) and text_11 notes no language restriction, but it does not specify other report characteristics such as dissemination year. Thus report-characteristic eligibility is only partially specified."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "(figure) \"54 Randomised trial with no results\" (listed among reasons for exclusion in the study selection flow diagram).",
      "reason": "The flow diagram lists exclusions for 'randomised trial with no results', indicating some differentiation of trials lacking results; however, the text/evidence does not explicitly explain or distinguish exclusions due to outcomes not being measured versus outcomes measured but not reported, so the distinction is only partially addressed."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Randomisedtrials in which people at risk of covid-19 were allocated to prophylaxis or no prophylaxis (standard care or placebo). Pairs of reviewers independently screened potentially eligible articles.",
      "reason": "The review specifies the groups used in syntheses (prophylaxis versus no prophylaxis/standard care/placebo), linking these groups to the comparisons of interest defined in the objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": "text_13",
      "quote": "Weexcluded randomised trials published only as press releases and trials that evaluated vaccination, nutrition, and non-drug supportive care interventions.",
      "reason": "While notable exclusions are listed (e.g., press-release-only trials, vaccination, nutrition, non-drug supportive care), the manuscript does not provide rationales explaining why these specific restrictions were applied."
    }
  ],
  "confidence": 85
}

